INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 45, 'theory', 'Quiz: state and layers');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 45, 0, 'Why does axum state usually contain an Arc inside?', '["It is a requirement of the Rust language", "The state is cloned for every request, and Arc clones only the reference counter and keeps the data shared", "Arc speeds up the network", "Without Arc you cannot use async"]', 1, 'State: Clone is cloned per request; Arc makes the clone cheap and shares the data.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 45, 1, 'What must you not do with a std::sync::MutexGuard in an async handler?', '["Read the value", "Hold it across .await", "Use it in a closure", "Pass it to a function"]', 1, 'The guard is not Send and blocks other tasks; release the lock before the await or use tokio::sync::Mutex.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 45, 2, 'Which layer ends up outermost in Router::layer(A).layer(B)?', '["A", "B: the last one added wraps everything before it", "They are equal", "It depends on the type names"]', 1, 'layer wraps everything added before it, so the last layer sees the request first.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 45, 3, 'How does route_layer differ from layer?', '["No difference", "route_layer applies only to existing routes and does not affect requests to nonexistent paths", "route_layer is faster", "route_layer is for POST only"]', 1, 'layer wraps the fallback too, route_layer only the matched routes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 45, 4, 'What status does the body size limit layer return when the limit is exceeded?', '["400", "408", "413", "500"]', 2, '413 Payload Too Large; 408 is the request timeout.');
